# Settings shared by every script. Do not edit this file: copy settings.example.sh to
# settings.local.sh and edit that, or export the variables in your shell.
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
[ -f "$HERE/settings.local.sh" ] && . "$HERE/settings.local.sh"

# Workspace-Bench checkout with workspace-bench.patch applied and the workspaces downloaded.
: "${WB_REPO:?set WB_REPO to your Workspace-Bench checkout (see README)}"

# Evolve agent and judge (Claude). Set ANTHROPIC_API_KEY, or leave it empty to use a
# Claude subscription login stored in CLAUDE_CREDS.
: "${ANTHROPIC_API_KEY:=}"
: "${CLAUDE_CREDS:=$HOME/.claude/.credentials.json}"
# Optional: pin the evolve agent's model (empty = Claude Code's default).
: "${EVOLVE_MODEL:=}"

# Target agent (Codex). Set GPT54MINI_API_KEY (and GPT54MINI_BASE_URL), or leave the key empty
# to use a ChatGPT subscription login stored in CODEX_HOME_HOST.
: "${GPT54MINI_API_KEY:=}"
: "${GPT54MINI_BASE_URL:=}"
: "${CODEX_HOME_HOST:=$HOME/.codex}"

# Docker socket. Target runs are launched from inside the evolve container through this socket.
if [ -z "${DOCKER_SOCK:-}" ]; then
  case "${DOCKER_HOST:-}" in
    unix://*) DOCKER_SOCK="${DOCKER_HOST#unix://}";;
    *) if [ -S "/run/user/$(id -u)/docker.sock" ]; then DOCKER_SOCK="/run/user/$(id -u)/docker.sock"
       else DOCKER_SOCK=/var/run/docker.sock; fi;;
  esac
fi
export DOCKER_HOST="unix://$DOCKER_SOCK"

export WB_REPO ANTHROPIC_API_KEY CLAUDE_CREDS EVOLVE_MODEL GPT54MINI_API_KEY GPT54MINI_BASE_URL CODEX_HOME_HOST DOCKER_SOCK
